#pragma once

// The blocks from after Beta 1.8 (1.21's building and colored blocks), as data:
// ModernBlocksData.h is generated by tools/modern_blocks.py. BlocksModern.cpp
// registers them; ModernTextures packs their textures into terrain.png.
// Data only (plus the block and item enums), so the texture tool can include it too.

#include "Items.h"

enum class ModernKind {
    Cube, Pillar, Stairs, Slab, Wall, Fence, FenceGate, Door, Trapdoor, PressurePlate, Button, Carpet, Pane, Glazed, Chain
};

// Hardness, blast resistance, material and sound, from 1.21's block properties.
enum class ModernPreset {
    Log, Planks, NetherWood, Stone, Cobble, Deepslate, Reinforced, Brick, Mud, Sandstone, Lantern, NetherBrick, Basalt,
    EndStone, Metal, Netherite, Quartz, Amethyst, Copper, Wool, Terracotta, Concrete, Powder, Glass
};

enum ModernFlag : unsigned {
    MB_ANYTHING = 1 << 0,    // pressure plate: anything on it, not just mobs
    MB_WOODEN = 1 << 1,      // button: wooden (stays pressed longer)
    MB_IRON = 1 << 2,        // trapdoor: only redstone opens it
    MB_LIGHT = 1 << 3,       // gives off light 15
    MB_POWER = 1 << 4,       // always a redstone power source
    MB_CUTOUT = 1 << 5,      // see-through holes
    MB_TRANSLUCENT = 1 << 6, // blended, like water
    MB_HIDE_SAME = 1 << 7,   // no faces between two of it (glass)
    MB_DARK = 1 << 8,        // blocks light (tinted glass)
    MB_FALLING = 1 << 9,     // falls like sand; hardens into `base` touching water
};

struct ModernBlockSpec {
    const char* name;    // 1.21's ID, e.g. "spruce_planks"
    const char* display; // its English name
    ModernKind kind;
    ModernPreset preset;
    const char* tex;     // the texture (sides); slab: a side texture of its own
    const char* top;     // top/end texture (nullptr = tex)
    const char* bottom;  // bottom texture (nullptr = top, or tex)
    const char* base;    // stairs/slab/wall: the block it's made of; door: top texture;
                         // pane: edge texture; concrete powder: what it hardens into
    const char* item;    // door: the item's texture
    unsigned flags;
};

struct BetaEquivalent {
    const char* name; // 1.21's ID
    int id;           // this game's block or item
    int meta;
};

#include "ModernBlocksData.h"

// A 1.21 block or item name as this game has it (BlocksModern.cpp): false if it hasn't.
bool LookupBlockName(const char* name, int& id, int& meta);
